/* Продолжение planirovshik.html: единое состояние недели, расчёты и показ платформы */
'use strict';
const M=window.PlannerModel;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,d=1)=>Number(v||0).toLocaleString('ru-RU',{maximumFractionDigits:d});
const money=v=>n(v/1e6,2)+' млн';
const delta=v=>(v>0?'+':v<0?'−':'')+n(Math.abs(v)/1000,1)+' тыс';
const clone=o=>JSON.parse(JSON.stringify(o));
const icon=(name)=>{const paths={plan:'M3 5h18M3 12h18M3 19h18M7 3v4M16 10v4M10 17v4',demand:'M4 19V9h4v10M10 19V5h4v14M16 19V12h4v7',scenarios:'M3 6h18M3 12h18M3 18h18M8 3v6M16 9v6M11 15v6',approval:'M9 12l3 3 7-8M5 3h9M5 3v18h14v-6',actual:'M3 18h18M5 15V7M10 15v-4M15 15V5M20 15v-6',effect:'M3 18l5-6 5 2 7-10M14 4h6v6'};return `<svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.plan}"/></svg>`};
const VIEWS=[['plan','План недели'],['demand','Спрос и сделки'],['scenarios','Рычаги и варианты'],['approval','Согласование'],['actual','План–факт'],['effect','Эффект решения']];
const defaultState=()=>({p:M.defaults(),view:'plan',product:'fillet',confirms:{commercial:false,production:false,finance:false},approved:null,revision:1,request:{quantity:4,price:300,service:0,requestId:'demo-order-1',forecastAbsorption:true},roi:{weeks:52,execution:0.7,investment:null,annualOpex:null},client:{volume:10,share:75,price:205,service:15},capacityTab:'scenario'});
let S=defaultState(),modal=null,tour=-1,returnFocus=null,requestResult=null,toastTimer,tourOpener=null;
try {const saved=JSON.parse(localStorage.getItem('severnaya-planner-v3')||'null');if(saved&&saved.schema===3){S={...S,...saved.state,p:{...M.defaults(),...saved.state.p}};if(!M.evaluate(S.p).valid)S=defaultState()}}catch(e){}
function persist(){try{localStorage.setItem('severnaya-planner-v3',JSON.stringify({schema:3,state:S}))}catch(e){toast('Сохранение в браузере требует доступного хранилища')}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3800)}
function changed(){S.confirms={commercial:false,production:false,finance:false};S.revision++;requestResult=null;persist()}
function setPath(obj,path,value){const parts=path.split('.');const last=parts.pop();let a=obj;for(const p of parts){if(!a[p])a[p]={};a=a[p]}a[last]=value}
const pathGet=(obj,path)=>path.split('.').reduce((o,k)=>o?.[k],obj);
function read(){const r=M.evaluate(S.p), a=M.alternatives(S.p);return {r,a,base:a.baseline?.result||M.evaluate({...S.p,route:'fillet',cut:S.p.totalInput*.4})}}
function prodName(k){return M.products[k]?.name||({whole:'Тушка',fillet:'Филе',legs:'Ножки',wing:'Крыло',frame:'Каркас',breast:'Грудка на кости',legMeat:'Мясо ножки',bone:'Кость',skin:'Кожа'}[k])||k}
function status(level,label){return `<span class="status" data-level="${level}"><span class="status-symbol">${{ok:'✓',watch:'!',bad:'!',info:'○'}[level]}</span>${esc(label)}</span>`}
const hint=(text)=>`data-tip="${esc(text)}" tabindex="0"`;
function metric(label,value,note,tip){return `<div class="metric" ${label.includes('Вклад')?'data-action="economics" role="button"':''} ${hint(tip||note)}><label>${label}</label><strong class="${/Требуется|Требует|База требует|Вложения 0/.test(value)?'disabled-value':''}">${value}</strong><small>${note}</small></div>`}
function field(label,path,{min=0,max=100,step=1,unit='',type='number',scope='p'}={}){let v=pathGet(S[scope],path);return `<div class="lever-field"><label for="f-${scope}-${path.replaceAll('.','-')}">${label}</label><div class="field-row"><input id="f-${scope}-${path.replaceAll('.','-')}" type="${type}" data-scope="${scope}" data-param="${path}" min="${min}" max="${max}" step="${step}" value="${esc(v??'')}" ${scope==='p'&&path==='cut'&&S.p.route==='whole'?'disabled':''} ${v===null?'placeholder="Введите"':''}><span class="field-unit">${unit}</span></div></div>`}
function routeSelect(){return `<div class="lever-field"><label for="route">Схема разделки</label><select id="route" data-param="route" data-scope="p">${Object.entries(M.routes).map(([id,r])=>`<option value="${id}" ${S.p.route===id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div>`}
function head(eye,title,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eye}</div><h1>${title}</h1></div><div class="heading-actions"><button class="secondary mobile-parameters" data-action="parameters">Параметры</button>${action}</div></div>`}
function panel(title,body,foot=''){return `<section class="visual-pane"><div class="visual-header"><h2>${title}</h2></div>${body}${foot?`<div class="source-note">${foot}</div>`:''}</section>`}
function actionPane(title,body){return `<aside class="action-pane"><div class="eyebrow">Рычаги решения</div><h2>${title}</h2>${body}</aside>`}
function actionSignal(title,detail,action,level='watch'){return `<button class="signal-item" data-action="${action}"><span class="signal-head">${status(level,level==='bad'?'Требует решения':level==='ok'?'Проверено':'Проверить')}</span><span class="signal-title">${title}</span><span class="signal-meta">${detail}</span><span class="signal-link">Открыть причину →</span></button>`}
function productRows(r){return Object.entries(r.produced||{}).filter(([k,v])=>v>1e-8&&k!=='loss').map(([k,v])=>({id:k,qty:v}))}
function soldQty(r,k){const a=r.allocations?.[k];if(typeof a==='number')return a;return a?.sold??a?.soldT??a?.allocated??Math.min(r.produced?.[k]||0,S.p.demand?.[k]||0)}
function flowSVG(r){const rows=productRows(r),W=950,H=370,top=58,dy=Math.min(46,254/Math.max(1,rows.length-1));const total=S.p.totalInput,whole=r.whole??total-S.p.cut;let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Баланс массы: вход ${n(total)} тонн, тушка ${n(whole)} тонн, разделка ${n(S.p.cut)} тонн, потери ${n(r.loss)} тонн"><text x="18" y="20" class="svg-muted">Вход после охлаждения</text><text x="240" y="20" class="svg-muted">Маршруты</text><text x="490" y="20" class="svg-muted">Совместный выход</text><text x="765" y="20" class="svg-muted">Продажи / остаток</text>`;
s+=`<path d="M172 170C208 170 196 95 230 95M172 170C208 170 196 239 230 239" class="flow-link"/><rect x="18" y="115" width="154" height="113" rx="5" fill="#003c72"/><text x="36" y="146" fill="white" font-size="15">Охлаждённая тушка</text><text x="36" y="187" fill="white" font-size="34" font-weight="600">${n(total)} т</text><text x="36" y="210" fill="white" font-size="13">${n(S.p.rawCost)} руб / кг</text><rect x="230" y="57" width="186" height="78" fill="#F1F3F5" rx="4"/><text x="248" y="83" font-size="16">Целая тушка</text><text x="248" y="112" font-size="26" fill="#003c72">${n(whole)} т</text><rect x="230" y="191" width="186" height="104" fill="#F1F3F5" rx="4"/><text x="248" y="218" font-size="16">Вход разделки</text><text x="248" y="251" font-size="26" fill="#003c72">${n(S.p.cut)} т</text><text x="248" y="275" font-size="13">${esc(M.routes[S.p.route]?.name||'')}</text>`;
rows.forEach((row,i)=>{const y=top+i*dy,sourceY=row.id==='whole'?95:239,sold=soldQty(r,row.id),left=Math.max(0,row.qty-sold),width=210*row.qty/Math.max(...rows.map(x=>x.qty),1);s+=`<path d="M416 ${sourceY}C450 ${sourceY} 449 ${y+13} 480 ${y+13}" class="flow-link thin"/><text x="490" y="${y+3}" font-size="15">${esc(prodName(row.id))}</text><rect x="490" y="${y+12}" width="${width}" height="7" fill="${row.id==='whole'?'#9FAAB5':'#003c72'}"/><text x="721" y="${y+8}" text-anchor="end" font-size="16" font-weight="600">${n(row.qty)} т</text><text x="765" y="${y+8}" font-size="16" fill="${left>0?'#B03A2E':'#1A1A1A'}">${n(sold)} / ${n(left)} т</text>`});
s+=`<text x="490" y="340" font-size="14" fill="#666666">Технологические потери</text><text x="721" y="340" text-anchor="end" font-size="16">${n(r.loss)} т</text><text x="18" y="359" font-size="13" fill="#666666">Баланс: выпуск + потери = ${n(total)} т входа</text></svg>`;return s}
function stageBars(r,compact=false){return `<div class="stage-list ${compact?'compact':''}">${(r.stages||[]).filter(s=>s.active!==false).map(s=>`<button class="stage-row" data-action="capacity" ${hint(`${s.name}: ${n(s.load)} из ${n(s.capacity)} ${s.unit}. ${s.sourceStatus}`)}><span class="stage-name">${s.name}</span><span class="stage-bar"><span class="stage-fill ${s.load>s.capacity?'risk':''}" style="width:${s.utilization===null?100:Math.min(100,s.utilization*100)}%"></span></span><span class="stage-value ${s.utilization>1?'negative':''}">${s.utilization===null?'0 т':n(s.utilization*100,0)+'%'}</span></button>`).join('')}</div>`}
function home(){const {r,a,base}=read();const bottleneck=(r.stages||[]).filter(s=>s.active!==false).sort((a,b)=>(b.utilization??1e9)-(a.utilization??1e9))[0];return head('Решение недели / вся корзина',r.feasible?'План связывает выпуск с продажами и вкладом':'Ограничения определяют следующий шаг плана',`<button class="secondary" data-action="tour">Показать платформу</button>`)+`<div class="metrics" id="metrics">${metric('Вклад недели',money(r.contribution)+' ₽','После сырья и переменных затрат','Вклад = текущие продажи − сырьё − переменные затраты. Общие постоянные расходы учитываются отдельно')}${metric('Изменение к базе',a.comparable?delta(r.contribution-base.contribution)+' ₽':'База требует проверки','База: 40% входа в разделку','Сравнение с исходной схемой филе и частей при тех же внешних ценах и ограничениях')}${metric('Запас мощности',bottleneck?n(Math.max(0,1-(bottleneck.utilization??1))*100,0)+'%':'0%',bottleneck?.name||'Переделы',bottleneck?'Самая высокая загрузка среди переделов учебной модели':'Учебная модель')}</div><div class="workspace">${panel('Каждая часть получает место в плане',`<div class="chart-area" id="flow"><div class="desktop-flow">${flowSVG(r)}</div>${mobileFlow(r)}</div><div class="stage-summary"><div class="section-inline"><h3>Переделы ограничивают объём</h3><button class="text-button" data-action="capacity">Все мощности →</button></div>${stageBars(r,true)}</div>`,'Учебные нормы / массы в тоннах / продажи текущей недели')}${actionPane('Выберите маршрут',`<div id="home-levers">${routeSelect()}${field('Вход разделки','cut',{max:S.p.totalInput,step:1,unit:'т'})}</div><button class="text-button" data-action="routes">Как тушка превращается в продукты →</button>${actionSignal(r.feasible?'План укладывается в условия':'Условия требуют изменения',r.feasible?'Сравните вклад доступных вариантов':esc((r.violations||[])[0]||'Проверьте параметры'),'scenarios',r.feasible?'ok':'bad')}<button class="primary" data-view="scenarios">Сравнить варианты</button>`)}</div>`}
function demand(){const {r}=read(), k=S.product, produced=r.produced[k]||0,ordered=r.allocations[k]?.orders||0,demand=S.p.demand[k]||0,forecast=Math.max(0,demand-ordered),sold=soldQty(r,k);const pOptions=Object.keys(M.products).filter(k=>k!=='loss');return head('Коммерция / обязательства и возможности','Спрос связывает цену с доступной корзиной',`<button class="secondary" data-action="commercial">Условия сделки</button>`)+`<div class="metrics">${metric('Выпуск выбранной части',n(produced)+' т',prodName(k))}${metric('Подтверждённые заказы',n(ordered)+' т','Резерв учитывается однократно')}${metric('Прогноз сверх заказов',n(forecast)+' т','Общий спрос '+n(demand)+' т')}</div><div class="workspace">${panel('Заказы поглощают прогноз по выбранной части',`<div class="product-picker"><label for="product">Продукт</label><select id="product" data-ui="product">${pOptions.map(id=>`<option value="${id}" ${id===k?'selected':''}>${esc(prodName(id))}</option>`).join('')}</select><button class="text-button" data-action="prices">Цены и спрос →</button></div><div class="demand-visual" id="demand-chart">${horizontalBars([{name:'Общий спрос',value:demand},{name:'Заказы в составе спроса',value:ordered},{name:'Доступный выпуск',value:produced},{name:'Размещено в плане',value:sold}],Math.max(demand,produced,1),'т')}</div><div class="allocation-explain"><div><h3>Заказ закрепляет объём</h3><p>Новая заявка заменяет равный объём прогноза в пределах общей потребности</p></div><div><h3>Разделка создаёт корзину</h3><p>Дополнительный вход одновременно увеличивает выход каждой части</p></div></div>`,'Проверка заявки учитывает текущий сценарий, мощности и всю корзину')}${actionPane('Проверьте заявку',`${field('Объём заявки','quantity',{scope:'request',max:1000,step:.1,unit:'т'})}${field('Цена после обслуживания','price',{scope:'request',max:2000,step:1,unit:'руб / кг'})}<button class="primary" data-action="check-request">Проверить заявку</button><div id="request-result">${requestMarkup()}</div><button class="text-button" data-action="commercial">Оценить смену клиента →</button>`)}</div>`}
function requestMarkup(){if(!requestResult)return '<p class="mini-note">Проверка покажет физическое покрытие, сопутствующие продукты и экономику</p>';const q=requestResult;return `<div class="request-feedback">${status(q.canApply?'ok':'watch',q.canApply?'Условия проверены':'Требует решения')}<h3>${esc(q.message||q.summary||'Результат проверки заявки')}</h3><div class="request-stats"><div><span>Покрытие заявки</span><strong>${n(q.covered??q.acceptedQuantity)} т</strong></div><div><span>К текущему вкладу</span><strong>${delta(q.deltaContribution||0)} ₽</strong></div></div><p>Дополнительная разделка ${n(q.extraCut)} т / уточнение прогноза ${n(q.forecastConsumed)} т</p>${q.shortfall>0?`<p class="negative">Другой срок или источник: ${n(q.shortfall)} т</p>`:''}${(q.errors||q.violations||q.reasons||[]).slice(0,2).map(x=>`<p>${esc(x)}</p>`).join('')}${q.params?`<button class="secondary" data-action="apply-request" ${q.canApply?'':'disabled'}>Включить в сценарий</button>`:''}</div>`}
function horizontalBars(items,max,unit){return `<div class="desktop-chart"><svg viewBox="0 0 900 280" role="img" aria-label="Сопоставление объёмов">${items.map((x,i)=>{const y=24+i*62;return `<text x="5" y="${y+20}" font-size="17">${esc(x.name)}</text><rect x="263" y="${y}" width="${Math.max(0,x.value)/max*470}" height="32" rx="2" fill="${i===2?'#003c72':'#A9B4BE'}"/><text x="755" y="${y+22}" font-size="21" fill="#003c72">${n(x.value)} ${unit}</text>`}).join('')}</svg></div><div class="mobile-bars">${items.map((x,i)=>`<div class="mobile-bar-row"><div><span>${esc(x.name)}</span><strong>${n(x.value)} ${unit}</strong></div><span class="bar-track"><span style="width:${Math.max(0,x.value)/max*100}%;background:${i===2?'#003c72':'#A9B4BE'}"></span></span></div>`).join('')}</div>`}
function scenarios(){const {r,a,base}=read();const candidates=a.candidates||[];return head('Планирование / управляемые рычаги','Маршрут и мощности определяют выполнимый план',`<button class="secondary" data-action="levers">Все рычаги</button>`)+`<div class="metrics">${metric('Выбранный маршрут',n(S.p.cut)+' т',M.routes[S.p.route]?.name||'Разделка')}${metric('Вклад всей корзины',money(r.contribution)+' ₽','Спрос и цены текущего сценария')}${metric('Остаток на конец',n(r.inventoryT)+' т','Продажа остатка требует отдельного срока','Выручка будущей продажи раскрывается отдельно от вклада текущей недели')}</div><div class="workspace">${panel('Варианты сравниваются на одинаковой базе',`<div class="comparison" id="alternatives"><table class="data-table"><thead><tr><th>Вариант</th><th class="num">Разделка, т</th><th class="num">Вклад, млн ₽</th><th class="num">К базе, тыс ₽</th><th>Условия</th></tr></thead><tbody>${candidates.map((c,i)=>`<tr class="row-click ${Math.abs(c.params.cut-S.p.cut)<.001?'selected':''}" tabindex="0" data-candidate="${i}"><td>${esc(c.name||c.label||'Вариант '+(i+1))}${a.best?.id===c.id?'<small>Лучший из вариантов</small>':''}</td><td class="num">${n(c.params.cut)}</td><td class="num">${n(c.result.contribution/1e6,2)}</td><td class="num">${a.comparable?n((c.result.contribution-base.contribution)/1000,1):'База требует проверки'}</td><td>${status(c.result.feasible?'ok':'bad',c.result.feasible?'Выполним':'Требует решения')}</td></tr>`).join('')}</tbody></table></div><div class="capacity-block" id="bottlenecks"><div class="section-inline"><h3>Загрузка показывает ограничивающий передел</h3><button class="text-button" data-action="capacity">Карта мощности →</button></div>${stageBars(r)}<p class="mini-note">100% означает полный плановый ресурс передела</p></div>`,'Сравнение конечного набора вариантов / дополнительные схемы выбираются справа')}${actionPane('Измените условия',`${routeSelect()}${field('Вход разделки','cut',{max:S.p.totalInput,unit:'т'})}${field('Доступная разделка','capacity',{max:300,unit:'т / неделя'})}${field('Обязательства по тушке','minWhole',{max:S.p.totalInput,unit:'т'})}<button class="text-button" data-action="routes">Схемы и нормы →</button><button class="primary" data-view="approval" ${r.feasible?'':'disabled'}>Перейти к согласованию</button>`)}</div>`}
function approvals(){const {r}=read();const items=[['commercial','Коммерция','Спрос, цены и обязательства'],['production','Производство','Маршруты, время и мощности'],['finance','Финансы','Цена сырья и изменяемые затраты']];const all=items.every(([id])=>S.confirms[id]);return head('Исполнение / единая версия','Подтверждения закрепляют выбранную корзину')+`<div class="metrics">${metric('Вклад согласуемого плана',money(r.contribution)+' ₽',M.routes[S.p.route]?.name||'')}${metric('Вход разделки',n(S.p.cut)+' т','Из '+n(S.p.totalInput)+' т сырья')}${metric('Подтверждения',items.filter(([id])=>S.confirms[id]).length+' / 3','Текущая версия параметров')}</div><div class="workspace">${panel('Каждая функция подтверждает свои условия',`<div class="approval-flow" id="confirmations">${items.map(([id,name,description],i)=>`<label class="approval-step"><span class="step-number">${i+1}</span><div><h3>${name}</h3><p>${description}</p></div><input type="checkbox" data-confirm="${id}" ${S.confirms[id]?'checked':''}><span class="approval-label">${S.confirms[id]?'Подтверждено':'Подтвердить'}</span></label>`).join('')}</div><div class="version-proof"><h3>Версия сохраняет условия решения</h3><div class="version-values"><span>Тушка<strong>${n(r.whole)} т</strong></span><span>Разделка<strong>${n(S.p.cut)} т</strong></span><span>Вклад<strong>${money(r.contribution)} ₽</strong></span></div><p class="mini-note">Изменение параметров запускает новый круг подтверждений</p></div>`,'Демонстрация согласования / сохранение действует в этом браузере')}${actionPane('Закрепите решение',`${actionSignal(r.feasible?'Проверки пройдены':'Условия требуют изменения',r.feasible?'Материальный баланс и ресурсы согласованы':esc((r.violations||[]).join('; ')),'capacity',r.feasible?'ok':'bad')}<button class="primary" data-action="approve" ${all&&r.feasible?'':'disabled'}>Утвердить версию</button>${S.approved?`<p class="mini-note">Сохранена версия ${esc(S.approved.label||'В1')}</p><button class="secondary" data-action="tasks">Открыть задания</button>`:'<p class="mini-note">Три подтверждения открывают утверждение</p>'}<button class="text-button" data-view="actual">Посмотреть план–факт →</button>`)}</div>`}
function actual(){const p=S.approved?.params||S.p;const f=M.fact(p),plan=typeof f.plan==='number'?f.plan:M.evaluate(p).contribution,actual=typeof f.actual==='number'?f.actual:plan+(f.delta||0);const price=f.priceDelta||0,cost=f.costDelta||0;return head('Контроль / причины отклонений','Цена и затраты объясняют изменение вклада',`<button class="secondary" data-action="fact-details">Разобрать причины</button>`)+`<div class="metrics">${metric(S.approved?'Утверждённый вклад':'Вклад текущего сценария',money(plan)+' ₽',S.approved?.label||'Предварительный просмотр')}${metric('Учебный факт',money(actual)+' ₽','Те же объёмы и размещение')}${metric('Отклонение',delta(actual-plan)+' ₽',n(plan?((actual-plan)/plan*100):0,1)+'% к плану')}</div><div class="workspace">${panel('Изменения цены и затрат сходятся с результатом',`<div class="chart-area" id="variance-chart">${waterfall([{name:'План',value:plan,total:true},{name:'Цена филе',value:price},{name:'Затраты разделки',value:cost},{name:'Учебный факт',value:actual,total:true}])}</div><div class="factor-summary"><div><span class="eyebrow">Коммерция</span><h3>${delta(price)} ₽</h3><p>Цена филе ${n(Math.max(0,p.prices.fillet-5))} руб / кг</p></div><div><span class="eyebrow">Производство</span><h3>${delta(cost)} ₽</h3><p>Затраты разделки +0,2 руб / кг входа</p></div></div>`,'Учебный факт / цена филе и затраты изменены / остальные условия плана сохранены')}${actionPane('Свяжите причину с действием',`${actionSignal('Коммерция проверяет цену','Сверка фактических цен, скидок и условий реализации','fact-details','watch')}${actionSignal('Производство проверяет затраты','Сверка переменных расходов выбранного маршрута','fact-details','watch')}<button class="primary" data-view="scenarios">Обновить сценарий</button>`)}</div>`}
function waterfall(items){const W=900,H=330,step=W/items.length,barWidth=step*.68,max=Math.max(...items.filter(x=>x.total).map(x=>x.value),1)*1.12,min=Math.min(0,...items.filter(x=>x.total).map(x=>x.value)),Y=v=>H-55-(v-min)/(max-min)*(H-90);let running=0;return `<div class="desktop-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Мост вклада от плана к факту">${items.map((x,i)=>{let start=x.total?0:running,end=x.total?x.value:running+x.value;running=end;const bx=12+i*step,by=Y(Math.max(start,end)),bh=Math.max(2,Math.abs(Y(start)-Y(end)));return `<rect x="${bx}" y="${by}" width="${barWidth}" height="${bh}" fill="${x.total?'#003c72':x.value<0?'#B03A2E':'#849BAD'}" rx="3"/><text x="${bx}" y="${by-12}" fill="${x.value<0?'#B03A2E':'#003c72'}" font-size="23" font-weight="600">${x.total?money(x.value):delta(x.value)}</text><text x="${bx}" y="${H-23}" font-size="17">${x.name}</text>${i<items.length-1?`<path d="M${bx+barWidth} ${Y(end)}H${bx+step}" stroke="#A9B4BE" stroke-dasharray="4 4"/>`:''}`}).join('')}<text x="20" y="327" fill="#666666" font-size="13">Рубли / изменение вклада всей корзины</text></svg></div><div class="mobile-bars">${items.map(x=>`<div class="mobile-bar-row"><div><span>${x.name}</span><strong class="${x.value<0?'negative':''}">${x.total?money(x.value):delta(x.value)} ₽</strong></div><span class="bar-track"><span style="width:${Math.min(100,Math.abs(x.value)/max*100)}%;background:${x.value<0?'#B03A2E':'#003c72'}"></span></span></div>`).join('')}</div>`}
function effect(){const {r,base}=read(),calc=M.roi(S.p,S.roi),eligible=calc.eligible===true,weekly=r.contribution-base.contribution,annual=eligible?calc.annualEffect:null,complete=S.roi.investment!==null&&S.roi.annualOpex!==null,net=eligible?annual-(S.roi.annualOpex||0):null,payback=calc.paybackYears!==null&&calc.paybackYears!==undefined?calc.paybackYears*12:null;return head('Экономика / от улучшения к деньгам','Эффект связывает решение с сопоставимой базой',`<button class="secondary" data-action="roi-method">Метод расчёта</button>`)+`<div class="metrics">${metric('Изменение за неделю',delta(weekly)+' ₽','Текущий сценарий к базе 40%')}${metric('Условный годовой эффект',eligible?money(annual)+' ₽':'Требуется проверка',n(S.roi.weeks,0)+' недель × '+n(S.roi.execution*100,0)+'% реализации')}${metric('Окупаемость проекта',complete&&eligible?(S.roi.investment===0?'Вложения 0 руб':payback!==null?n(payback,1)+' мес':'Требует положительного потока'):'Требуется бюджет','До налогов и изменения оборотного капитала')}</div><div class="workspace">${panel('Календарь и исполнение определяют результат',`${eligible?'':`<div class="eligibility-note">${esc((calc.errors||[]).join('; '))}</div>`}<div class="effect-equation" id="effect-equation"><div><span>Эффект недели</span><strong>${delta(weekly)} ₽</strong></div><b>×</b><div><span>Периодов</span><strong>${n(S.roi.weeks,0)}</strong></div><b>×</b><div><span>Реализация</span><strong>${n(S.roi.execution*100,0)}%</strong></div><b>=</b><div class="equation-total"><span>Эффект года</span><strong>${eligible?money(annual)+' ₽':'Требуется проверка'}</strong></div></div><div class="economics-bridge"><h3>Денежная модель учитывает расходы проекта</h3><table class="data-table"><tbody><tr><td>Операционный эффект</td><td class="num">${eligible?money(annual)+' ₽':'Требуется проверка'}</td></tr><tr><td>Ежегодное сопровождение</td><td class="num">${S.roi.annualOpex===null?'Требуется ввод':n(S.roi.annualOpex/1000)+' тыс ₽'}</td></tr><tr><td>Разовые вложения</td><td class="num">${S.roi.investment===null?'Требуется ввод':money(S.roi.investment)+' ₽'}</td></tr><tr><td>Налоги и оборотный капитал</td><td class="num">Подтверждают финансы</td></tr></tbody></table></div><p class="mini-note">Условный повтор выбранной недели. Реальный год рассчитывается по календарю спроса, цен, мощностей и запасов</p>`,'Учебная чувствительность / потенциальный эффект и подтверждённый результат учитываются отдельно')}${actionPane('Задайте условия',`${field('Недель в расчёте','weeks',{scope:'roi',min:1,max:53,unit:'недель'})}<div class="lever-field"><label for="exec-percent">Доля реализации</label><div class="field-row"><input id="exec-percent" type="number" min="0" max="100" value="${n(S.roi.execution*100,0)}" data-ui="execution"><span class="field-unit">%</span></div></div>${field('Разовые вложения','investment',{scope:'roi',max:1e10,step:100000,unit:'руб'})}${field('Сопровождение за год','annualOpex',{scope:'roi',max:1e10,step:10000,unit:'руб'})}<button class="text-button" data-action="roi-method">Как подтвердить эффект →</button>`)}</div>`}
function render(){if(!VIEWS.some(([id])=>id===S.view))S.view='plan';$('#navigation').innerHTML=VIEWS.map(([id,label],i)=>`<button class="nav-button ${S.view===id?'active':''}" data-view="${id}" ${S.view===id?'aria-current="page"':''}><span class="nav-icon">${icon(id)}</span><span class="nav-label"><span class="nav-label-long">${label}</span><span class="nav-label-short">${['План','Спрос','Варианты','Версия','План–факт','Эффект'][i]}</span></span><span class="nav-number">${i+1}</span></button>`).join('');const validation=M.evaluate(S.p);S.p=validation.params;$('#content').innerHTML=validation.valid?({plan:home,demand,scenarios,approval:approvals,actual,effect}[S.view])():head('Проверка ввода','Параметры требуют согласования')+`<section class="invalid-state"><h2>Уточните условия сценария</h2>${validation.errors.map(x=>`<p>${esc(x)}</p>`).join('')}<div><button class="primary" data-action="levers">Открыть параметры</button> <button class="secondary" data-action="prices">Проверить спрос</button> <button class="secondary" data-action="reset">Восстановить пример</button></div></section>`;$('#version-status').textContent=S.approved&&JSON.stringify(S.approved.params)===JSON.stringify(S.p)?S.approved.label+' / утверждена':'Черновик П'+S.revision;$('#context-line').textContent='Учебная модель / '+n(S.p.totalInput)+' т охлаждённой тушки / руб';bindHints();if(tour>=0)positionTour()}
function go(view){closeModal();S.view=view;history.replaceState(null,'','#'+view);persist();render()}
function openModal(kind,tab){returnFocus=document.activeElement;modal={kind,tab:tab||'main'};updateModal();$('#overlay').classList.remove('hidden');$('.modal').focus()}
function closeModal(){if(!modal)return;modal=null;$('#overlay').classList.add('hidden');returnFocus?.focus?.()}
function tabButtons(tabs){return tabs.map(([id,text])=>`<button class="${modal.tab===id?'active':''}" data-modal-tab="${id}">${text}</button>`).join('')}
function updateModal(){if(!modal)return;const {r}=read();let title='',eye='',body='',tabs='',footer='';const kind=modal.kind;
if(kind==='parameters'&&innerWidth<=768){title='Управляйте текущим решением';eye=VIEWS.find(x=>x[0]===S.view)?.[1]||'';body='<div class="action-pane">'+($('.action-pane')?.innerHTML||'')+'</div>';footer='<button class="primary" data-action="close">Вернуться к экрану</button>'}
else if(kind==='levers'||kind==='parameters'){title='Рычаги меняют всю экономику сценария';eye='Управляемые условия';tabs=tabButtons([['main','Сырьё и маршруты'],['resources','Мощности'],['market','Спрос и цена']]);if(modal.tab==='resources')body=`<div class="modal-grid">${field('Разделка за неделю','capacity',{max:1000,unit:'т'})}${field('Рабочее время разделки','hours',{max:168,unit:'ч'})}${field('Скорость разделки','rate',{max:100,step:.025,unit:'т / ч'})}${field('Обвалка за неделю','stageCapacity.deboning',{max:1000,unit:'т входа'})}${field('Упаковка за неделю','stageCapacity.packing',{max:1000,unit:'т выпуска'})}${field('Заморозка за неделю','stageCapacity.freezing',{max:1000,unit:'т'})}${field('Ёмкость холода','coldCapacity',{max:1000,unit:'т запаса'})}</div><p class="mini-note">Разделка ограничена меньшим из двух значений: тоннаж либо время × скорость</p>`;else if(modal.tab==='market')body=priceForm();else body=`<div class="modal-grid">${field('Вход охлаждённой тушки','totalInput',{min:1,max:1000,unit:'т'})}${field('Цена сырья','rawCost',{min:0,max:2000,unit:'руб / кг'})}${routeSelect()}${field('Затраты маршрута','routeCosts.'+S.p.route,{max:500,step:.1,unit:'руб / кг входа'})}${field('Вход разделки','cut',{max:S.p.totalInput,unit:'т'})}${field('Обязательства по тушке','minWhole',{max:S.p.totalInput,unit:'т'})}</div><div class="explanation-row"><h3>Поставщики влияют на цену и условия поставки</h3><p>Вход модели задаётся после убоя и охлаждения. Живой вес, выход тушки, сортность и сроки требуют отдельного согласования</p></div>`;footer='<span>Каждое изменение обновляет черновик и его проверки</span><button class="primary" data-action="close">Вернуться к сценарию</button>'}
else if(kind==='routes'){eye='Производственные варианты';title='Схема разделки задаёт совместный выход';tabs=tabButtons([['main','Схемы'],['tree','Дерево операций'],['rules','Правила модели']]);if(modal.tab==='tree')body=`<div class="operation-tree"><div><h3>Тушка</h3><p>Продажа целиком либо разделка</p></div><div><h3>Грудка</h3><p>Грудка на кости либо филе, грудная кость и кожа</p><h3>Ножка</h3><p>Целая ножка либо бедро и голень; обвалка выделяет мясо, кость и кожу</p></div><div><h3>Прочие выходы</h3><p>Крылья, каркас, обрезь, технологические потери</p><h3>Последующие операции</h3><p>Упаковка, охлаждение, заморозка и хранение</p></div></div><p class="source-note">Основа: калькулятор_годовой.xlsx, лист «Справочник разделки», 169 строк / схема макета агрегирует подробные операции</p>`;else if(modal.tab==='rules')body=`<div class="method-list"><h3>Материальный баланс закрывает каждую тонну</h3><p>Выходы и технологические потери суммируются до входа маршрута</p><h3>Заказы задают жёсткие обязательства</h3><p>Выбор схемы проверяется по требуемым продуктам и мощности; сроки получают детализацию в промышленной модели</p><h3>Совместные продукты оцениваются одной корзиной</h3><p>Выручка всех частей сопоставляется с сырьём, затратами переделов и альтернативным маршрутом</p><h3>Нормы действуют для конкретного сырья</h3><p>Весовая категория, сортность, оборудование и дата нормы входят в паспорт промышленной модели</p></div>`;else body=`<div class="route-grid">${Object.entries(M.routes).map(([id,x])=>`<button class="route-choice ${S.p.route===id?'active':''}" data-route="${id}"><span class="route-name">${esc(x.name)}</span><span class="route-desc">${Object.entries(x.yields||{}).map(([k,v])=>`${esc(prodName(k))} ${n(v*100)}%`).join(' / ')}</span><span class="route-cost">${n(x.variableCost)} руб / кг входа</span><span class="source-note">${esc(x.sourceStatus||'Учебные коэффициенты')}</span></button>`).join('')}</div>`;footer='<span>Четыре агрегированные схемы / подробная карта поддерживает дальнейшую детализацию</span>'}
else if(kind==='capacity'){title=modal.tab==='source'?'Карта показывает ограничения исходного сценария':'Переделы определяют предел выбранного маршрута';eye='Мощности и узкие места';tabs=tabButtons([['main','Сценарий'],['source-primary','Первичные'],['source-cut','Разделка'],['source','Упаковка'],['actions','Решения']]);if(modal.tab.startsWith('source'))body=capacitySource(modal.tab);else if(modal.tab==='actions')body=`<div class="method-list"><h3>Планирование меняет маршрут и календарь</h3><p>Перенос объёма, выбор схемы разделки, сменность и последовательность партий меняют загрузку операций</p><h3>Производство увеличивает полезное время</h3><p>Сокращение простоев и переналадок оценивается в часах ограничивающего передела</p><h3>Коммерция согласует состав и срок заказа</h3><p>Продажа другой части или перенос даты меняют нагрузку и вклад всей корзины</p><h3>Финансы оценивают цену расширения</h3><p>Дополнительный вклад сравнивается с оплатой смены, услуг и вложениями; расчёт повторяется после сдвига ограничения</p></div>`;else body=`<table class="data-table"><thead><tr><th>Передел</th><th class="num">Нагрузка, т</th><th class="num">Ресурс, т</th><th class="num">Загрузка</th><th>Статус</th></tr></thead><tbody>${(r.stages||[]).filter(x=>x.active!==false).map(x=>`<tr><td>${x.name}</td><td class="num">${n(x.load)}</td><td class="num">${n(x.capacity)}</td><td class="num">${x.utilization===null?'Ресурс 0':n(x.utilization*100)+'%'}</td><td>${status(x.load>x.capacity?'bad':x.utilization>=.95?'watch':'ok',x.load>x.capacity?'Превышение':x.utilization>=.95?'На пределе':'Есть резерв')}</td></tr>`).join('')}</tbody></table><div class="storage-line"><h3>Хранение ограничивает запас</h3><p>${n(r.storage?.load??r.inventoryT)} т из ${n(r.storage?.capacity??S.p.coldCapacity)} т единовременно</p></div><p class="mini-note">Учебные мощности модели / тоннаж потока и ёмкость хранения учитываются раздельно</p>`;footer='<button class="secondary" data-action="levers-resources">Изменить доступные мощности</button>'}
else if(kind==='prices'){title='Цена и спрос определяют размещение корзины';eye='Коммерческие рычаги';body=priceForm();footer='<span>Прогноз включает подтверждённые заказы</span>'}
else if(kind==='commercial'){title='Условия сделки меняют вклад всей корзины';eye='Отдельная проверка коммерческого решения';tabs=tabButtons([['main','Смена клиента'],['discount','Скидка'],['purchase','Поставщики']]);if(modal.tab==='discount')body=`<div class="method-list"><h3>Правило скидки меняет результат заказа</h3><table class="data-table"><thead><tr><th>Учебное условие</th><th class="num">Объём, т</th><th class="num">Вклад, тыс ₽</th></tr></thead><tbody><tr><td>Исходная цена 200 руб / кг</td><td class="num">10</td><td class="num">300</td></tr><tr><td>190 руб / кг на дополнительные 2 т</td><td class="num">12</td><td class="num">340</td></tr><tr><td>190 руб / кг на все 12 т</td><td class="num">12</td><td class="num">240</td></tr></tbody></table><p>Учебная себестоимость 170 руб / кг. Разница правил скидки составляет 100 тыс руб</p><p class="source-note">Паспорт расчётов, раздел «Правило скидки» / самостоятельный пример</p></div>`;else if(modal.tab==='purchase')body=`<div class="method-list"><h3>Цена поставки переводится в цену пригодного входа</h3><p>Покупная цена, транспорт, выход годной тушки, сортность и потери задают сопоставимую стоимость сырья</p><h3>Партия проверяется по весу и сроку</h3><p>Весовая категория влияет на выход частей и скорость оборудования; календарь поставки связывается с заказами</p><h3>Условия оплаты влияют на денежный поток</h3><p>Отсрочка, минимальная партия и надёжность поставщика оцениваются вместе с оборотным капиталом</p></div><button class="primary" data-action="levers">Изменить цену и объём сырья</button>`;else {const c=S.client,a=c.share/100,net=c.price-c.service,change=c.volume*1000*(net*a+135*(1-a)-180),threshold=net>135?45/(net-135)*100:null;body=`<div class="modal-grid">${field('Свободный объём ножек','volume',{scope:'client',max:1000,step:.1,unit:'т'})}${field('Замещение объёма','share',{scope:'client',max:100,unit:'%'})}${field('Цена нового клиента','price',{scope:'client',max:2000,unit:'руб / кг'})}${field('Обслуживание клиента','service',{scope:'client',max:1000,unit:'руб / кг'})}</div><div class="client-result"><div><span>Изменение вклада</span><strong class="${change<0?'negative':''}">${delta(change)} ₽</strong></div><div><span>Порог замещения</span><strong>${threshold===null?'Требует более высокой цены':n(threshold)+'%'}</strong></div></div><p class="mini-note">База после обслуживания: 180 руб / кг. Реализация остатка после заморозки: 135 руб / кг. Горизонт включает будущую продажу</p>`}footer='<span>Самостоятельная чувствительность / общий эффект требует совместного пересчёта</span>'}
else if(kind==='data'||kind==='sources'){title='Источники отделяют факт от учебных условий';eye='Данные и готовность';tabs=tabButtons([['main','Потоки данных'],['sources','Источники'],['quality','Контроль качества']]);if(modal.tab==='sources')body=`<div class="source-register"><div><strong>Планировщик и концепция</strong><p>planirovshik.html, архив severnaya-week-planner.zip, паспорт расчётов и сценарии от 12 октября 2026</p></div><div><strong>Производство и экономика</strong><p>Карта мощности от 29 сентября, годовой калькулятор, модель маржинальности v5, эффективность разделки, калькуляторы и примеры таблиц</p></div><div><strong>Дизайн и доказательные визуалы</strong><p>Гайд по дизайну v3, презентации планирования и 20261001_EN_RB_V6, четыре приложенные иллюстрации</p></div><div><strong>Метод</strong><p><a href="https://www.accaglobal.com/gb/en/student/exam-support-resources/fundamentals-exams-study-resources/f5/technical-articles/relevant-costs.html" target="_blank" rel="noopener">ACCA: изменяемые затраты</a><br><a href="https://research.tue.nl/en/publications/production-planning-and-control-of-poultry-processing-plants/" target="_blank" rel="noopener">Исследование планирования птицепереработки</a></p></div></div>`;else if(modal.tab==='quality')body=`<div class="method-list"><h3>Каждый набор получает паспорт</h3><p>Владелец, дата среза, единицы, охват и статус сверки сопровождают показатель</p><h3>Нормы проходят проверку суммы</h3><p>Годовой справочник содержит округлённые нормы 100,0214% и 100,1% в отдельных узлах; учебные нормы отдельно замыкают баланс; производственные коэффициенты подтверждает технолог</p><h3>Формулы требуют контрольного пересчёта</h3><p>Карта мощности содержит три сохранённые ошибки формул. Показанные мощности взяты из проверенных числовых ячеек расчётного листа</p><h3>Обновление сохраняет историю версии</h3><p>Каждый расчёт связывает срез данных, параметры, алгоритм и подтверждения владельцев</p></div>`;else body=`<table class="data-table source-table"><thead><tr><th>Набор</th><th>Зачем нужен</th><th>Владелец</th><th>Статус макета</th></tr></thead><tbody>${[['Выпуск и убой','Вход, сортность, выход','Производство','Учебный срез'],['Заказы, прогноз и цены','Спрос и обязательства','Коммерция','Учебный срез'],['Остатки и сроки','Запасы и годность','Склад','Учебный срез'],['Затраты и условия','Вклад и денежный поток','Финансы','Учебные условия'],['Нормы разделки','Совместный выход','Технолог','Учебные нормы'],['Переделы и мощности','Предел маршрута','Производство','Исходная карта']].map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table><p class="mini-note">Основная часть обмена данными обсуждена в проекте. Промышленное подключение каждого набора подтверждается владельцем и контрольной сверкой</p>`;footer='<span>Этот публичный макет выполняет локальные расчёты на учебных данных</span>'}
else if(kind==='economics'){title='Выручка всей корзины покрывает изменяемые затраты';eye='Расчёт вклада текущей недели';body=`<div class="cost-chart">${waterfall([{name:'Выручка',value:r.revenue,total:true},{name:'Сырьё',value:-r.rawCost},{name:'Переделы',value:-r.routeCost},{name:'Обслуживание',value:-r.serviceCost},{name:'Заморозка',value:-r.freezeCost},{name:'Вклад',value:r.contribution,total:true}])}</div><div class="method-list"><p>Переделы: тушка ${n(r.whole)} т × ${n(S.p.routeCosts.whole)} руб / кг + разделка ${n(r.cut)} т × ${n(S.p.routeCosts[S.p.route])} руб / кг</p><p>Оценка будущей реализации остатка: ${money(r.inventoryValue)} руб. Общие постоянные расходы, налоги и вложения рассматриваются отдельно</p></div>`;footer='<button class="secondary" data-action="levers">Изменить вводные</button>'}
else if(kind==='fact-details'){title='Цена и расходы объясняют отклонение';eye='Проверка план–факт';const p=S.approved?.params||S.p,f=M.fact(p),er=M.evaluate(p);body=`<table class="data-table"><thead><tr><th>Причина</th><th>Формула</th><th class="num">Изменение, тыс ₽</th></tr></thead><tbody><tr><td>Цена филе</td><td>${n(soldQty(er,'fillet'))} т × 1 000 × −5 руб / кг</td><td class="num">${n(f.priceDelta/1000)}</td></tr><tr><td>Затраты разделки</td><td>${n(p.cut)} т × 1 000 × −0,2 руб / кг</td><td class="num">${n(f.costDelta/1000)}</td></tr></tbody></table><div class="method-list"><h3>В промышленной версии мост охватывает все причины</h3><p>Объём → состав корзины → цена → сырьё → выход → переделы → запасы</p><p>Фиксированный порядок подстановки относит каждое взаимодействие факторов к одному шагу</p></div>`;footer='<span>План–факт измеряет исполнение / эффект решения измеряется относительно сопоставимой альтернативы</span>'}
else if(kind==='roi-method'){title='Сопоставимая база защищает расчёт эффекта';eye='Финансовая модель';body=`<div class="method-list"><h3>Вклад отражает экономику всей корзины</h3><p>Продажи текущей недели − сырьё − переменные расходы выбранного маршрута − дополнительные расходы остатка</p><h3>Запасы связывают периоды</h3><p>Будущая выручка и учётная стоимость запасов раскрываются отдельными величинами</p><h3>Эффект сравнивает равные внешние условия</h3><p>Одинаковые спрос, цены, сырьё и календарь позволяют выделить влияние решения</p><h3>Проект оценивается по денежному потоку</h3><p>Реализованный эффект − сопровождение − вложения − налоги − прирост оборотного капитала</p><h3>Пилот подтверждает реализованный результат</h3><p>Финансы сверяют версии, базу, фактические продажи и затраты за согласованный период</p></div>`;footer='<span>Окупаемость в макете рассчитывается при явном вводе бюджета</span>'}
else if(kind==='tasks'||kind==='version'){title='Версия связывает параметры с исполнением';eye='Сохранённый снимок';const p=S.approved?.params||S.p,er=M.evaluate(p);body=`<div class="method-list"><h3>${S.approved?esc(S.approved.label):'Текущий черновик'}</h3><p>${esc(M.routes[p.route]?.name||'')} / вход разделки ${n(p.cut)} т / вклад ${money(er.contribution)} руб</p><table class="data-table"><thead><tr><th>Функция</th><th>Задание версии</th></tr></thead><tbody><tr><td>Производство</td><td>Подготовить ${n(p.cut)} т входа по выбранной схеме</td></tr><tr><td>Коммерция</td><td>Разместить совместную корзину в пределах подтверждённых условий</td></tr><tr><td>Склад</td><td>Зарезервировать ${n(er.inventoryT)} т конечного остатка</td></tr><tr><td>Финансы</td><td>Сверить вклад ${money(er.contribution)} руб и причины отклонения</td></tr></tbody></table></div>`;footer='<span>Демонстрационные задания сохранены в браузере</span><button class="secondary" data-action="export">Скачать версию</button>'}
else {title='Рычаги связывают решения с результатом фабрики';eye='Концепция платформы';tabs=tabButtons([['main','Логика'],['scope','Границы'],['roadmap','Развитие']]);if(modal.tab==='scope')body=`<div class="method-list"><h3>Макет исполняет локальные сценарии</h3><p>Четыре агрегированные схемы разделки, спрос по продуктам, мощности, сравнение вариантов и версия плана работают на учебных данных</p><h3>Промышленная модель раскрывает подробности</h3><p>Весовые категории, сортность, партии, сроки, маршруты оборудования, клиенты, скидки и многопериодные запасы уточняются по источникам</p><h3>Подключение данных проходит приёмку</h3><p>Владельцы подтверждают доступность, свежесть, единицы и полноту каждого набора</p></div>`;else if(modal.tab==='roadmap')body=`<div class="method-list"><h3>Владельцы подтверждают модель и источники</h3><p>Технологи сверяют выходы, производство – мощности, коммерция – спрос, финансы – экономику</p><h3>Пилот проверяет решения на истории</h3><p>Совместная сверка физического баланса, ограничений и денежных последствий выявляет расхождения</p><h3>Пользователи проверяют рабочий цикл</h3><p>Новая заявка, смена схемы, перегруз передела, остаток, утверждение и разбор факта проходят приёмку</p><h3>Промышленный контур закрепляет управление</h3><p>Роли, журнал действий, версии, автоматическое обновление и контроль качества поддерживают регулярное планирование</p></div>`;else body=`<div class="concept-map"><div><h3>Что меняем</h3><p>Сырьё и поставки<br>Маршрут и ресурсы<br>Спрос и условия сделки</p></div><div><h3>Что проверяем</h3><p>Баланс каждой части<br>Обязательства и сроки<br>Мощности и остатки</p></div><div><h3>Что получаем</h3><p>Выполнимый план<br>Вклад всей корзины<br>Объяснимое отклонение</p></div></div><p class="mini-note">План, спрос, варианты, согласование, план–факт и эффект используют единое состояние расчёта</p>`;footer='<button class="secondary" data-action="reset">Восстановить учебный пример</button>'}
$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eye;$('#modal-tabs').innerHTML=tabs;$('#modal-body').innerHTML=body;$('#modal-footer').innerHTML=footer;bindHints()}
function priceForm(){const k=S.product;return `<div class="product-picker"><label for="modal-product">Продукт</label><select id="modal-product" data-ui="product">${Object.keys(M.products).map(id=>`<option value="${id}" ${id===k?'selected':''}>${esc(prodName(id))}</option>`).join('')}</select></div><div class="modal-grid">${field('Цена реализации','prices.'+k,{max:2000,unit:'руб / кг'})}${field('Общий спрос','demand.'+k,{max:1000,step:.1,unit:'т'})}${field('Подтверждённые заказы','orders.'+k,{max:1000,step:.1,unit:'т'})}${field('Затраты обслуживания','service.'+k,{max:1000,unit:'руб / кг'})}</div><p class="mini-note">Заказы входят в общий спрос. Изменение цены относится ко всему объёму выбранного продукта; индивидуальная заявка рассчитывается отдельно</p>`}
function capacitySource(group='source'){
const data={
'source-primary':[['Приёмка птицы',735.126,888.964,'11','Живой вес'],['Убой',735.126,888.964,'13','Живой вес'],['Потрошение',29.809,32.198,'15','Поток потрохов'],['Водяное охлаждение',735.126,888.964,'16','Живой вес*'],['Холодильник тушки',735.126,888.964,'17','Живой вес*'],['Сортировка',735.126,888.964,'18','Живой вес*']],
'source-cut':[['Разделка STORK + MEYN',197.6042,213.40616,'24','Продукты разделки'],['Филе грудки',36.291,61.824,'25','Готовое филе'],['Филе бедра',5.786,11.088,'26','Готовое филе']],
'source':[['Тушка навалом',313.222,337.272,'19','Упакованная тушка'],['Индивидуальная тушка',43.094,69.384,'20','Упакованная тушка'],['Обработка ливера',16.61761,15.174,'21','Ливер'],['Упаковка субпродуктов',11.078,18.144,'22','Субпродукты'],['Упаковка лап',22.15682,17.58,'23','Лапы'],['Упаковка ISHIDA',33.972,49.69,'27','Готовые продукты']]};
const rows=data[group]||data.source;return `<div class="source-period">Сохранённый сценарий книги / период требует подтверждения</div><table class="data-table capacity-source"><thead><tr><th>Передел / база массы</th><th class="num">Нагрузка, т / сутки</th><th class="num">Ресурс, т / сутки</th><th class="num">Загрузка</th><th>Строка</th></tr></thead><tbody>${rows.map(([name,load,cap,row,basis])=>`<tr><td>${name}<small>${basis}</small></td><td class="num">${n(load,2)}</td><td class="num">${n(cap,2)}</td><td class="num ${load>cap?'negative':''}">${n(load/cap*100,1)}%</td><td>${row}</td></tr>`).join('')}</tbody></table><div class="source-takeaway">${group==='source-primary'?'<h3>Первичные операции сохраняют базу исходного расчёта</h3><p>* Книга переносит поток живого веса на охлаждение и холодильник. Ёмкость хранения и поток готовой тушки требуют отдельных норм</p>':group==='source-cut'?'<h3>Численность ограничивает доступный ресурс разделки</h3><p>Книга задаёт 22 человека на STORK и 34 на MEYN. Совместная мощность людей 15,6 т / ч сопоставляется с номиналом линий 27,8 т / ч</p>':'<h3>Упаковка лап ограничивает исходный сценарий</h3><p>Превышение мощности: 4,58 т в сутки. Лапы относятся к субпродуктам; ножки тушки проходят собственные операции</p>'}</div><p class="source-note">Карта мощности от 29 сентября, лист 2.2 / D: нагрузка, F: мощность, G: загрузка / базы массы сохранены по книге</p>`}
const TOUR=[['plan','#flow','Начните с результата всей корзины','Одна тушка даёт несколько связанных продуктов. План показывает массу каждого выхода и вклад всей недели'],['plan','#home-levers','Выберите способ разделки','Маршрут меняет выход продуктов, затраты и потребность в оборудовании'],['demand','#demand-chart','Проверьте обязательства и спрос','Заказы входят в общий спрос. Заявка получает собственный резерв и проверку доступного выпуска'],['scenarios','#bottlenecks','Найдите ограничивающий передел','Загрузка показывает, где дополнительная тонна требует изменения маршрута, времени или мощности'],['scenarios','#alternatives','Выберите выполнимый вариант','Сравнение использует одинаковые внешние условия и результат всех совместных продуктов'],['approval','#confirmations','Закрепите условия одной версией','Коммерция, производство и финансы подтверждают текущие параметры перед утверждением'],['actual','#variance-chart','Свяжите отклонение с причиной','План–факт раскрывает влияние цены и затрат, ответственного и следующее действие'],['effect','#effect-equation','Переведите решение в проверяемый эффект','Календарь, исполнение и затраты проекта связывают улучшение недели с денежным результатом']];
function startTour(){tourOpener=document.activeElement;closeModal();tour=0;showTour()}
function endTour(){tour=-1;$('#tour-layer').classList.add('hidden');const opener=tourOpener?.isConnected?tourOpener:$('[data-action="tour"]');opener?.focus();persist()}
function showTour(){if(tour>=TOUR.length){endTour();toast('Показ завершён. Параметры доступны для самостоятельной проверки');return}S.view=TOUR[tour][0];render();$('#tour-layer').classList.remove('hidden');const card=$('.tour-card');$('.tour-counter').textContent='Шаг '+(tour+1)+' из '+TOUR.length;card.querySelector('h3').textContent=TOUR[tour][2];card.querySelector('p').textContent=TOUR[tour][3];$('[data-action="tour-prev"]').disabled=tour===0;$('[data-action="tour-next"]').textContent=tour===TOUR.length-1?'Завершить':'Далее';requestAnimationFrame(positionTour);card.focus()}
function positionTour(){if(tour<0)return;const selected=$(TOUR[tour][1]),target=selected?.offsetHeight?selected:$('.metrics'),spot=$('.tour-spot'),card=$('.tour-card');if(!target)return;const r=target.getBoundingClientRect(),w=Math.min(340,innerWidth-32);Object.assign(spot.style,{left:Math.max(8,r.left-5)+'px',top:Math.max(8,r.top-5)+'px',width:Math.min(r.width+10,innerWidth-16)+'px',height:Math.min(r.height+10,innerHeight-16)+'px'});card.style.width=w+'px';let x=r.right+18,y=r.top;if(x+w>innerWidth-16){x=Math.max(16,r.left);y=r.bottom+18}const h=card.offsetHeight||236;if(y+h>innerHeight-16){y=Math.max(16,r.top-h-18);if(y<70){y=innerHeight-h-16;x=innerWidth-w-16}}Object.assign(card.style,{left:Math.min(innerWidth-w-16,x)+'px',top:Math.max(16,Math.min(innerHeight-h-16,y))+'px'})}
function bindHints(){$$('[data-tip]').forEach(el=>{el.onmouseenter=el.onfocus=()=>{if(tour>=0)return;const tip=$('#tooltip');tip.textContent=el.dataset.tip;tip.classList.remove('hidden');const r=el.getBoundingClientRect();tip.style.left=Math.min(innerWidth-290,Math.max(8,r.left))+'px';tip.style.top=Math.min(innerHeight-tip.offsetHeight-10,r.bottom+8)+'px'};el.onmouseleave=el.onblur=()=>$('#tooltip').classList.add('hidden')})}
function download(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({status:'Учебный пример',version:S.approved||{params:S.p},exported:new Date().toISOString()},null,2)],{type:'application/json'}));a.href=url;a.download='Северная_версия_плана.json';a.click();URL.revokeObjectURL(url)}
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.param){const scope=t.dataset.scope||'p';let val=t.type==='number'?Number(t.value):t.value;if(t.type==='number'&&(t.value===''||!Number.isFinite(val))){if(scope==='roi')val=null;else {render();if(modal)updateModal();toast('Введите число в пределах поля');return}}if(t.type==='number'&&val!==null){val=Math.max(Number(t.min||0),Math.min(Number(t.max||1e12),val))}setPath(S[scope],t.dataset.param,val);if(scope==='request')requestResult=null;if(scope==='p'){if(t.dataset.param==='totalInput'){S.p.cut=Math.min(S.p.cut,val)}if(t.dataset.param==='route'&&val==='whole')S.p.cut=0;if(t.dataset.param==='minWhole')S.p.orders.whole=val;changed()}persist();render();if(modal)updateModal()}
if(t.dataset.ui==='product'){S.product=t.value;requestResult=null;render();if(modal)updateModal()}
if(t.dataset.ui==='execution'){S.roi.execution=Math.max(0,Math.min(1,Number(t.value)/100));persist();render()}
if(t.dataset.confirm){S.confirms[t.dataset.confirm]=t.checked;persist();render()}});
document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-candidate],[data-action]');if(!t)return;$('#tooltip').classList.add('hidden');if(t.dataset.view){go(t.dataset.view);return}if(t.dataset.candidate!==undefined){const c=read().a.candidates[Number(t.dataset.candidate)];if(c){S.p=clone(c.params);changed();render();toast('Вариант выбран. Подтверждения относятся к новым условиям')}return}if(t.dataset.route){S.p.route=t.dataset.route;if(S.p.route==='whole')S.p.cut=0;else if(S.p.cut===0)S.p.cut=Math.min(S.p.capacity,S.p.totalInput-S.p.minWhole);changed();render();updateModal();return}if(t.dataset.modalTab){modal.tab=t.dataset.modalTab;updateModal();return}const a=t.dataset.action;if(!a)return;
if(a==='close')closeModal();else if(a==='tour')startTour();else if(a==='tour-close'){endTour()}else if(a==='tour-next'){tour++;showTour()}else if(a==='tour-prev'){tour=Math.max(0,tour-1);showTour()}else if(a==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){toast('Используйте полноэкранный режим браузера')}}else if(a==='scenarios')go('scenarios');else if(a==='levers-resources')openModal('levers','resources');else if(a==='check-request'){requestResult=M.checkRequest(S.p,{...S.request,product:S.product});render();if(modal)updateModal();toast('Заявка проверена по корзине и ресурсам')}else if(a==='apply-request'){if(requestResult?.params&&requestResult.canApply===true){S.p=clone(requestResult.params);S.request.requestId='demo-order-'+Date.now();changed();render();if(modal)updateModal();toast('Заявка включена в учебный сценарий')}}else if(a==='approve'){try{const snapshot=M.snapshot(S.p,S.confirms);if(snapshot?.approved!==true){toast(snapshot.errors?.[0]||'Проверьте условия утверждения');return}S.approved={...snapshot,params:clone(snapshot.params),label:'В'+S.revision,createdAt:new Date().toISOString()};persist();render();if(modal)updateModal();toast('Версия '+S.approved.label+' сохранена в браузере')}catch(err){toast(err.message)}}else if(a==='export')download();else if(a==='reset'){S=defaultState();persist();closeModal();render();toast('Учебный пример восстановлен')}else openModal(a,a==='sources'?'sources':undefined)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(tour>=0){endTour()}else closeModal();$('#tooltip').classList.add('hidden');return}const activeLayer=tour>=0?$('.tour-card'):modal?$('.modal'):null;if(e.key==='Tab'&&activeLayer){const fs=[...activeLayer.querySelectorAll('button:not(:disabled),input,select,a[href],[tabindex="0"]')].filter(x=>x.offsetParent!==null);const first=fs[0],last=fs.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===activeLayer)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}return}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||modal)return;if(tour>=0){if(e.key==='ArrowRight'){tour++;showTour()}if(e.key==='ArrowLeft'){tour=Math.max(0,tour-1);showTour()}return}if(e.key==='?'||e.key==='F1'){e.preventDefault();startTour()}if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const i=VIEWS.findIndex(([id])=>id===S.view);go(VIEWS[Math.max(0,Math.min(VIEWS.length-1,i+(e.key==='ArrowRight'?1:-1)))][0])}if((e.key==='Enter'||e.key===' ')&&(e.target.dataset.candidate!==undefined||e.target.getAttribute('role')==='button')){e.preventDefault();e.target.click()}});
$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeModal()});window.addEventListener('resize',positionTour);window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(VIEWS.some(([v])=>v===id)){S.view=id;render()}});if(VIEWS.some(([id])=>id===location.hash.slice(1)))S.view=location.hash.slice(1);render();window.PlannerApp={getState:()=>clone(S),read,go,openModal,startTour};

function mobileFlow(r){return `<div class="mobile-flow"><div class="mobile-flow-head"><span>Вход ${n(S.p.totalInput)} т</span><span>Разделка ${n(r.cut)} т</span></div>${productRows(r).map(row=>`<div class="mobile-flow-row"><span>${esc(prodName(row.id))}</span><span class="num">${n(row.qty)} т</span><span class="num">${n(soldQty(r,row.id))} т продано</span><span class="bar-track"><span style="width:${row.qty/S.p.totalInput*100}%"></span></span></div>`).join('')}<span class="source-note">Технологические потери ${n(r.loss)} т</span></div>`}
